-- Data quality results: one row per test per run.
-- Generated by `python -m dbde render` from dbde/render.py. Do not edit: change the spec and render again.

CREATE SCHEMA IF NOT EXISTS ${gold_catalog}.ops;
-- GO

CREATE TABLE IF NOT EXISTS ${gold_catalog}.ops.DataQualityResult (
    LoadStepID      STRING    NOT NULL COMMENT 'Job run that ran the test.',
    Layer           STRING    NOT NULL COMMENT 'source, silver or gold.',
    TableName       STRING    NOT NULL COMMENT 'schema.Table tested.',
    TestName        STRING    NOT NULL COMMENT 'Test name, <kind>__<column>.',
    Severity        STRING    NOT NULL COMMENT 'error stops the load; warn is logged.',
    FailureCount    BIGINT    NOT NULL COMMENT 'Rows that failed (0 = pass).',
    TestedTimestamp TIMESTAMP NOT NULL COMMENT 'When the test ran (UTC).'
)
USING DELTA
COMMENT 'Data trust record: every data quality test result of every load.';
-- GO
